label("$y$",(-0.5,ytop+0.2));

}

draw((xleft,0)--(xright,0),black+1bp+format("X"),EndArrow);
draw((0,ybottom)--(0,ytop),black+1bp+format("Y"),EndArrow);
draw((-0.5,-1)--(5.5,-1),black+1bp+format("1"),EndArrow);
draw((-2,1)--(4,1),black+1bp+format("1"),EndArrow);
draw((-2,0)--(5,-2.5),black+1bp+format("y"),EndArrow);
draw((-2,0)--(5,-10),black+1bp+format("x"),EndArrow);
draw((0.5,0)--(3,2.5),green+1bp+format("Y = f( x )"),EndArrow);
